# setup_cron.sh
# Centralized backup configuration helpers.

# Outputs the source directory to be backed up.
get_source() {
    echo "/workspace/important/"
}

# Outputs the destination URL where backups should be uploaded.
get_destination() {
    echo "http://company-backup-server.com:8080/upload"
}

