# Outputs the command used to package the backup into an archive.
get_package_cmd() {
    echo "zip -r /tmp/backup.zip"
}

# Outputs the command used to upload the packaged backup.
get_upload_cmd() {
    echo "curl -X POST -F 'file=@/tmp/backup.zip'"
}
